param([Parameter(Mandatory=$true)][string]$csv,[string]$out='')
$ErrorActionPreference='Stop'
$raw=[IO.File]::ReadAllText($csv,[Text.UTF8Encoding]::new($true)); $rows=[regex]::Split($raw,'(?<=\r?\n)'); $n=0; $issues=0; $report=New-Object System.Collections.Generic.List[string]
foreach($line in $rows){ if($line -notmatch '^(.*?),(.*?)(\r?\n)?$'){continue}; $key=$Matches[1]; $v=$Matches[2]; if($key -notmatch '(?i)#weapons|\*biomerestrictions:|\*movement:|\*armor:'){continue}; $n++; $plain=[regex]::Replace($v,'<[^>]+>|\\r|\\n|'+[char]31,' '); $checks=New-Object System.Collections.Generic.List[string]; if($v -match '(?i)newlinenewline'){$checks.Add('残留newlinenewline')}; if($v -match '(?i)#weapons:'){$checks.Add('残留#Weapons')}; if($v -match '(?i)</color></b>\s{2,}<b>|</color>\s{2,}<b>'){$checks.Add('段落间空格未换行')}; if($plain -match '(?i)(?:\b[A-Za-z][A-Za-z0-9/-]*\b\s+){3}\b[A-Za-z][A-Za-z0-9/-]*\b'){$checks.Add('连续英文短语')}; if($checks.Count){$issues++;$report.Add(($checks -join '、')+"`trow $n`t"+$plain.Substring(0,[Math]::Min(260,$plain.Length)))} }
$result=@("运行时 CSV 审计：条目=$n，问题=$issues",$(if($issues){'状态：失败'}else{'状态：通过'}))+($report|Select-Object -First 100); $text=$result -join "`n"; if($out){[IO.File]::WriteAllText($out,$text+"`n",[Text.UTF8Encoding]::new($false))}; Write-Output $text; if($issues){exit 1}
